const CONTENT_RANGE_RE = /^bytes (\d+)-(\d+)\/(\d+)$/

function createUpload() {
  return {
    chunks: new Map(), // start -> Buffer
    total: null, // expected total size (from Content-Range)
    buffer: null, // assembled final buffer once complete
    forcedFailures: new Set(), // chunk indices that should 500 exactly once
    log: [], // successfully stored chunks: { index, start, end }
    attempts: [], // every PUT attempt: { index, start, end, status }
  }
