/**
 * In-memory chunked upload server.
 *
 * Routes:
 *   GET  /status?id=<uploadId>          -> {"received": <contiguous bytes stored>}
 *   PUT  /<anything>?id=<uploadId>      -> stores one chunk, honors Content-Range
 *   GET  /data?id=<uploadId>            -> final assembled buffer (once complete)
 *
 * Test hooks (attached to the returned http.Server):
 *   server.forceFail(id, chunkIndex)  force exactly one 500 on that chunk index
 *   server.getLog(id)                 successfully received chunks
 *   server.getAttempts(id)            every PUT attempt incl. rejected ones
 *   server.getBuffer(id)              final assembled buffer or null
 */
export function createServer() {
  /** @type {Map<string, ReturnType<typeof createUpload>>} */
  const uploads = new Map()

  function getUpload(id) {
    let u = uploads.get(id)
    if (!u) {
      u = createUpload()
      uploads.set(id, u)
    }
    return u
  }

  // Number of contiguous bytes stored starting at offset 0.
  function receivedBytes(u) {
    let contiguous = 0
    const starts = [...u.chunks.keys()].sort((a, b) => a - b)
    for (const start of starts) {
      if (start > contiguous) break
      contiguous = Math.max(contiguous, start + u.chunks.get(start).length)
    }
    return contiguous
  }

  function assembleIfComplete(u) {
    if (u.total !== null && receivedBytes(u) >= u.total && !u.buffer) {
      u.buffer = Buffer.concat(
        [...u.chunks.entries()].sort((a, b) => a[0] - b[0]).map(([, c]) => c),
      )
    }
  }

  function readBody(req) {
    return new Promise((resolve, reject) => {
      const parts = []
      req.on('data', (c) => parts.push(c))
      req.on('end', () => resolve(Buffer.concat(parts)))
      req.on('error', reject)
    })
  }

  function sendJson(res, status, obj) {
    res.writeHead(status, { 'content-type': 'application/json' })
    res.end(JSON.stringify(obj))
  }

  const server = http.createServer(async (req, res) => {
    try {
      const url = new URL(req.url, 'http://localhost')
      const id =
        url.searchParams.get('id') ?? req.headers['x-upload-id'] ?? null

      if (req.method === 'GET' && url.pathname === '/status') {
        const u = uploads.get(id)
        return sendJson(res, 200, { received: u ? receivedBytes(u) : 0 })
      }

      if (req.method === 'GET' && url.pathname === '/data') {
        const u = uploads.get(id)
        if (!u || !u.buffer) return sendJson(res, 404, { error: 'not complete' })
        res.writeHead(200, {
          'content-type': 'application/octet-stream',
          'content-length': u.buffer.length,
        })
        return res.end(u.buffer)
      }

      if (req.method === 'PUT') {
        const header = req.headers['content-range']
        const m = typeof header === 'string' ? CONTENT_RANGE_RE.exec(header) : null
        if (!id || !m) {
          return sendJson(res, 400, { error: 'missing id or valid Content-Range' })
        }
        const [, startStr, endStr, totalStr] = m
        const start = Number(startStr)
        const end = Number(endStr)
        const total = Number(totalStr)

        const u = getUpload(id)
        u.total = total
        const index = Math.floor(start / (end - start + 1))

        // Test hook: fail this exact chunk index exactly once.
        if (u.forcedFailures.has(index)) {
          u.forcedFailures.delete(index)
          u.attempts.push({ index, start, end, status: 500 })
          return sendJson(res, 500, { error: `injected failure on chunk ${index}` })
        }

        const body = await readBody(req)
        u.chunks.set(start, body)
        u.attempts.push({ index, start, end, status: 200 })
        u.log.push({ index, start, end })
        assembleIfComplete(u)

        return sendJson(res, 200, {
          received: receivedBytes(u),
          complete: Boolean(u.buffer),
        })
      }

      sendJson(res, 404, { error: 'unknown route' })
    } catch (err) {
      sendJson(res, 500, { error: String(err && err.message) })
    }
  })

  // ---- test hooks ----
  server.forceFail = (id, chunkIndex) => getUpload(id).forcedFailures.add(chunkIndex)
  server.getLog = (id) => getUpload(id).log
  server.getAttempts = (id) => getUpload(id).attempts
  server.getBuffer = (id) => uploads.get(id)?.buffer ?? null

  return server
}
