/**
 * Upload `buffer` in chunks to a chunk-upload server, with resume support.
 *
 * - Asks GET {endpoint}/status?id=<id> for the already-received byte offset
 *   and skips all chunks at or below it (resume after restart).
 * - PUTs each chunk with a "bytes start-end/total" Content-Range header and
 *   an X-Upload-Id header.
 * - Retries a failed chunk up to `retries` (default 2) times.
 * - Reports progress via onProgress(confirmedBytes) after each stored chunk;
 *   the initial server offset is reported immediately.
 *
 * Returns { id, received } where received is the total confirmed bytes.
 */
export async function upload(
  buffer,
  {
    chunkSize = 64 * 1024,
    endpoint,
    onProgress,
    id = crypto.randomUUID(),
    retries = 2,
    retryDelayMs = 25,
  } = {},
) {
  if (!endpoint) throw new Error('upload(): endpoint is required')
  if (!(chunkSize > 0)) throw new Error('upload(): chunkSize must be > 0')

  // Resume: ask the server how much it already has.
  const statusRes = await expectOk(
    `${endpoint}/status?id=${encodeURIComponent(id)}`,
    { method: 'GET' },
  )
  const { received } = await statusRes.json()

  let confirmed = Math.min(received, buffer.length)
  onProgress?.(confirmed)

  const total = buffer.length

  for (let index = Math.floor(received / chunkSize); index * chunkSize < total; index++) {
    const start = index * chunkSize
    const end = Math.min(start + chunkSize, total) - 1
    const chunk = buffer.subarray(start, end + 1)

    let attempt = 0
    for (;;) {
      try {
        await expectOk(endpoint, {
          method: 'PUT',
          headers: {
            'x-upload-id': id,
            'content-range': `bytes ${start}-${end}/${total}`,
            'content-type': 'application/octet-stream',
            'content-length': String(chunk.length),
          },
          body: chunk,
        })
        break
      } catch (err) {
        if (attempt >= retries) throw err
        attempt++
        await sleep(retryDelayMs * attempt)
      }
    }

    confirmed = end + 1
    onProgress?.(confirmed)
  }

  return { id, received: confirmed }
}
