test('full upload matches source buffer byte-for-byte', async (t) => {
  const { server, endpoint } = await startServer(t)
  const source = crypto.randomBytes(CHUNK * 3 + 12345) // non-multiple of chunkSize
  const seen = []

  const { id, received } = await upload(source, {
    endpoint,
    chunkSize: CHUNK,
    onProgress: (b) => seen.push(b),
  })

  assert.equal(received, source.length)
  // progress is monotonically increasing confirmed bytes, ending at total
  for (let i = 1; i < seen.length; i++) assert.ok(seen[i] > seen[i - 1])
  assert.equal(seen.at(-1), source.length)

  const stored = server.getBuffer(id)
  assert.ok(stored, 'server assembled the final buffer')
  assert.equal(stored.length, source.length)
  assert.equal(sha256(stored), sha256(source))
})

test('forced 500 on a chunk retries and upload still completes', async (t) => {
  const { server, endpoint } = await startServer(t)
  const source = crypto.randomBytes(CHUNK * 4)
  const id = crypto.randomUUID()

  server.forceFail(id, 2) // exactly one 500 on chunk index 2

  const { received } = await upload(source, { endpoint, chunkSize: CHUNK, id })
  assert.equal(received, source.length)

  // chunk 2 was attempted twice: one rejected attempt + one success
  const attemptsForChunk2 = server.getAttempts(id).filter((a) => a.index === 2)
  assert.deepEqual(
    attemptsForChunk2.map((a) => a.status),
    [500, 200],
